        {
            // Implement your logic here to initialize watchers for each extension
            StartObservingDirectory(@"path\to\your\directory", extension);
        }
    }

    private static void StartObservingDirectory(string path, string extension)
    {
        var fileSystemWatcher = new FileSystemWatcher();
        fileSystemWatcher.Path = path;
        fileSystemWatcher.IncludePattern = $"*.{extension}" + ".*";
        fileSystemWatcher.NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.Security;
        fileSystemWatcher.Changed += OnChanged;
        fileSystemWatcher.EnableRecursiveSubdirectoriesWatching(true); 
        fileSystemWatcher.ResumeSuspended();

        fileSystemWatcher.Start();
    }

    private async Task OnChanged(object sender, EventArgs eventArgs)
    {
        if (!await IsAllowedChange((EventArgs<VfsChanges>)(eventArgs))) return;

        var fullFilePath = ((FileSystemEventArgs)eventArgs).FullPath;
        var fileExtension = Path.GetExtension(fullFilePath);

        switch (fileExtension.Trim('.'))
