    }

    private void CompileScssAndSendCss()
    {
        // Logic to compile scss into css goes here...
        SendHotSwapMessage();
    }

    private void TriggerPageRefresh()
    {
        _broadcastCache.InvokeAsync("/refresh", null);
    }
}
